C
C Generated TIMESTAMP by SD/FAST, Kane's formulation
C (sdfast 2.0 #10001)
C
C
C ROADMAP (pend.sd)
C
C Bodies        Inb
C No  Name      body Joint type  Coords q
C --- --------- ---- ----------- ----------------
C   0 $ground                                    
C   1 pendulum    0  Pin           1             
C
C
      BLOCK DATA SDBLKDATA
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(1),INB(1),OUTB(1),NJNTDOF(1),NJNTC(1),NJNTP(1),
     & FIRSTQ(1),BALLQ(1),FIRSTM(1),FIRSTP(1)
      INTEGER TRANS(1)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      DOUBLE PRECISION GRAV(3),MK(1),IK(1,3,3),PIN(1,3)
      DOUBLE PRECISION RK(1,3),RI(1,3),PRES(1),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(1)
      INTEGER GRAVQ(3),MKQ(1),IKQ(1,3,3),PINQ(1,3),RKQ(1,3),RIQ(1,3),
     & PRESQ(1),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(1,3),RCOM(1,3),MKRCOMT(1,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(1),PSIK(1,3,3),
     & PSRCOM(1,3),PSRK(1,3),PSRI(1,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
C  Topological information
C
      DATA GROUND/1/
      DATA NBOD/1/
      DATA NDOF/1/
      DATA NCONS/0/
      DATA NLOOP/0/
      DATA NLDOF/0/
      DATA NLOOPC/0/
      DATA NBALL/0/
      DATA NLBALL/0/
      DATA NPRES/0/
      DATA NUSER/0/
      DATA JTYPE(1)/1/
      DATA INB(1)/0/
      DATA OUTB(1)/1/
      DATA NJNTDOF(1)/1/
      DATA NJNTC(1)/0/
      DATA NJNTP(1)/0/
      DATA FIRSTQ(1)/1/
      DATA BALLQ(1)/-103/
      DATA FIRSTM(1)/0/
      DATA FIRSTP(1)/0/
      DATA TRANS(1)/0/
C Model parameters from the input file
C
C gravity
      DATA GRAV(1)/0D0/
      DATA GRAV(2)/-9.8D0/
      DATA GRAV(3)/0D0/
C
C mass
      DATA MK(1)/10D0/
C
C inertia
      DATA IK(1,1,1)/5D0/
      DATA IK(1,1,2)/0D0/
      DATA IK(1,1,3)/0D0/
      DATA IK(1,2,1)/0D0/
      DATA IK(1,2,2)/1D0/
      DATA IK(1,2,3)/0D0/
      DATA IK(1,3,1)/0D0/
      DATA IK(1,3,2)/0D0/
      DATA IK(1,3,3)/5D0/
C
C tree hinge axis vectors
      DATA PIN(1,1)/0D0/
      DATA PIN(1,2)/0D0/
      DATA PIN(1,3)/1D0/
C
C tree bodytojoint vectors
      DATA RK(1,1)/0D0/
      DATA RK(1,2)/1.5D0/
      DATA RK(1,3)/0D0/
C
C tree inbtojoint vectors
      DATA RI(1,1)/0D0/
      DATA RI(1,2)/0D0/
      DATA RI(1,3)/0D0/
C
C tree prescribed motion
      DATA PRES(1)/0D0/
C
C stabilization parameters
      DATA STABVEL/0D0/
      DATA STABPOS/0D0/
C
C miscellaneous
      DATA MFRCFLG/0/
      DATA ROUSTATE/0/
      DATA VPKFLG/0/
      DATA INERFLG/0/
      DATA MMFLG/0/
      DATA MMLDUFLG/0/
      DATA WWFLG/0/
      DATA LTAUFLG/0/
      DATA FS0FLG/0/
      DATA II/0/
      DATA MMAP(1)/1/
C
C Which parameters were "?" (1) or "<nominal>?" (3)
      DATA GRAVQ(1)/0/
      DATA GRAVQ(2)/0/
      DATA GRAVQ(3)/0/
      DATA MKQ(1)/3/
      DATA IKQ(1,1,1)/0/
      DATA IKQ(1,1,2)/0/
      DATA IKQ(1,1,3)/0/
      DATA IKQ(1,2,1)/0/
      DATA IKQ(1,2,2)/0/
      DATA IKQ(1,2,3)/0/
      DATA IKQ(1,3,1)/0/
      DATA IKQ(1,3,2)/0/
      DATA IKQ(1,3,3)/0/
      DATA PINQ(1,1)/0/
      DATA PINQ(1,2)/0/
      DATA PINQ(1,3)/0/
      DATA RKQ(1,1)/0/
      DATA RKQ(1,2)/0/
      DATA RKQ(1,3)/0/
      DATA RIQ(1,1)/0/
      DATA RIQ(1,2)/0/
      DATA RIQ(1,3)/0/
      DATA PRESQ(1)/0/
      DATA STABVELQ/3/
      DATA STABPOSQ/3/
C
C End of values from input file
C
      END
C
      SUBROUTINE SDINIT
C
C
C Initialization routine
C
C
C  This routine must be called before the first call to sdstate(), after
C  supplying values for any `?' parameters in the input.
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(1),INB(1),OUTB(1),NJNTDOF(1),NJNTC(1),NJNTP(1),
     & FIRSTQ(1),BALLQ(1),FIRSTM(1),FIRSTP(1)
      INTEGER TRANS(1)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      DOUBLE PRECISION GRAV(3),MK(1),IK(1,3,3),PIN(1,3)
      DOUBLE PRECISION RK(1,3),RI(1,3),PRES(1),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(1)
      INTEGER GRAVQ(3),MKQ(1),IKQ(1,3,3),PINQ(1,3),RKQ(1,3),RIQ(1,3),
     & PRESQ(1),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(1,3),RCOM(1,3),MKRCOMT(1,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(1),PSIK(1,3,3),
     & PSRCOM(1,3),PSRK(1,3),PSRI(1,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION SUMSQ,NORMINV
      INTEGER I,J,K
      DOUBLE PRECISION CURTIM,Q(1),QN(1),U(1),CNK(1,3,3),CNB(1,3,3)
      DOUBLE PRECISION RNK(1,3),VNK(1,3),WK(1,3),RNB(1,3),VNB(1,3),WB(1,
     & 3),WBRCOM(1,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(1,3,3),RIKT(1,3,3),IKO(1,3,3),MKRK(1,3,3),CIB
     & (1,3,3)
      DOUBLE PRECISION WKK(1,3),VKK(1,3),DIK(1,3),RPP(1,3),RPK(1,3),RIK(
     & 1,3),RIK2(1,3)
      DOUBLE PRECISION RPRI(1,3),WIK(1,3),VIK(1,3),WIRK(1,3),RKWKK(1,3),
     & WKRPK(1,3),VIKWKR(1,3)
      DOUBLE PRECISION PERR(1),VERR(1),AERR(1),MULT(1),UFK(1,3),UTK(1,3)
     & ,MFK(1,3),MTK(1,3)
      DOUBLE PRECISION UTAU(1),MTAU(1),UACC(1),UVEL(1),UPOS(1)
      DOUBLE PRECISION S1,C1
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1
      DOUBLE PRECISION FS0(1),QDOT(1),OTK(1,3),ATK(1,3),AIOIWI(1,3),
     & FSTAR(1,3)
      DOUBLE PRECISION TSTAR(1,3),FSTARK(1,3),TSTARK(1,3),IKWK(1,3),
     & WKIKWK(1,3),GK(1,3),IKBWK(1,3),WKIKBWK(1,3)
      DOUBLE PRECISION W0W0(1),W1W1(1),W2W2(1),W0W1(1),W0W2(1),W1W2(1)
      DOUBLE PRECISION W00W11(1),W00W22(1),W11W22(1),WW(1,1),QRAUX(1)
      DOUBLE PRECISION MM(1,1),MLO(1,1),MDI(1),IKWPK(1,1,3),WORKS(1),
     & WORKSS(1,1)
      DOUBLE PRECISION WPK(1,1,3),VPK(1,1,3),VWRI(1,1,3)
      INTEGER WMAP(1),MULTMAP(1),JPVT(1),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(1),UDOT(1),TAUC(1),DYAD(1,3,3),FC(1,3),TC(1,3)
      DOUBLE PRECISION ANK(1,3),ONK(1,3),ONKB(1,3),AONKRI(1,3),ANKB(1,3)
     & ,ANKATK(1,3),ANB(1,3),ONB(1,3),DYRCOM(1,3)
      DOUBLE PRECISION FFK(1,3),TTK(1,3),FCCIKT(1,3),FFKB(1,3),TTKB(1,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      EXTERNAL SDBLKDATA
C
C
C Check that all `?' parameters have been assigned values
C
      DO 100 K=1,3
        IF (GRAVQ(K) .EQ. 1) THEN
          CALL SDSETERR(7,25)
        ENDIF
100   CONTINUE
      DO 140 K=1,1
        IF (MKQ(K) .EQ. 1) THEN
          CALL SDSETERR(7,26)
        ENDIF
        DO 130 I=1,3
          IF (RKQ(K,I) .EQ. 1) THEN
            CALL SDSETERR(7,29)
          ENDIF
          IF (RIQ(K,I) .EQ. 1) THEN
            CALL SDSETERR(7,30)
          ENDIF
          DO 120 J=1,3
            IF (IKQ(K,I,J) .EQ. 1) THEN
              CALL SDSETERR(7,27)
            ENDIF
120       CONTINUE
130     CONTINUE
140   CONTINUE
      DO 160 K=1,1
        DO 150 I=1,3
          IF (PINQ(K,I) .EQ. 1) THEN
            CALL SDSETERR(7,28)
          ENDIF
150     CONTINUE
160   CONTINUE
C
C Normalize pin vectors if necessary
C
C
C Zero out Vpk and Wpk
C
      DO 520 I=1,1
        DO 510 J=I,1
          DO 500 K=1,3
            VPK(I,J,K)= 0D0
            WPK(I,J,K)= 0D0
500       CONTINUE
510     CONTINUE
520   CONTINUE
C
C Compute pseudobody-related constants
C
      RCOM(1,1)= 0D0
      RCOM(1,2)= 0D0
      RCOM(1,3)= 0D0
C
C Compute mass properties-related constants
C
      MTOT= MK(1)
      IKO(1,1,1)= (5D0+(2.25D0*MK(1)))
      IKO(1,3,3)= (5D0+(2.25D0*MK(1)))
      CALL SDSERIALNO(I)
      IF (I .NE. 10001) THEN
        CALL SDSETERR(7,41)
      ENDIF
      ROUSTATE= 1
C
      RETURN
      END
C
C Convert state to form using 1-2-3 Euler angles for ball joints.
C
      SUBROUTINE SDST2ANG(ST,STANG)
      DOUBLE PRECISION ST(1),STANG(1)
C
      INTEGER I
C
      DO 100 I=1,1
        STANG(I)= ST(I)
100   CONTINUE
C
      RETURN
      END
C
C Convert 1-2-3 form of state back to Euler parameters for ball joints.
C
      SUBROUTINE SDANG2ST(STANG,ST)
      DOUBLE PRECISION STANG(1),ST(1)
C
      INTEGER I
C
      DO 100 I=1,1
        ST(I)= STANG(I)
100   CONTINUE
C
      RETURN
      END
C
C Normalize Euler parameters in state.
C
      SUBROUTINE SDNRMSTERR(ST,NORMST,ROUTINE)
      DOUBLE PRECISION ST(1),NORMST(1)
      INTEGER ROUTINE
C
      DOUBLE PRECISION GRAV(3),MK(1),IK(1,3,3),PIN(1,3)
      DOUBLE PRECISION RK(1,3),RI(1,3),PRES(1),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(1)
      INTEGER GRAVQ(3),MKQ(1),IKQ(1,3,3),PINQ(1,3),RKQ(1,3),RIQ(1,3),
     & PRESQ(1),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(1,3),RCOM(1,3),MKRCOMT(1,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(1),PSIK(1,3,3),
     & PSRCOM(1,3),PSRK(1,3),PSRI(1,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      INTEGER I
C
      DO 100 I=1,1
        NORMST(I)= ST(I)
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDNORMST(ST,NORMST)
      DOUBLE PRECISION ST(1),NORMST(1)
C
C
      CALL SDNRMSTERR(ST,NORMST,0)
C
      RETURN
      END
C
      SUBROUTINE SDSTATE(TIMEIN,QIN,UIN)
      DOUBLE PRECISION TIMEIN,QIN(1),UIN(1)
C
C
C Compute kinematic information and store it in sdgstate.
C
C Generated TIMESTAMP by SD/FAST, Kane's formulation
C (sdfast 2.0 #10001)
C
      DOUBLE PRECISION GRAV(3),MK(1),IK(1,3,3),PIN(1,3)
      DOUBLE PRECISION RK(1,3),RI(1,3),PRES(1),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(1)
      INTEGER GRAVQ(3),MKQ(1),IKQ(1,3,3),PINQ(1,3),RKQ(1,3),RIQ(1,3),
     & PRESQ(1),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(1,3),RCOM(1,3),MKRCOMT(1,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(1),PSIK(1,3,3),
     & PSRCOM(1,3),PSRK(1,3),PSRI(1,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(1),QN(1),U(1),CNK(1,3,3),CNB(1,3,3)
      DOUBLE PRECISION RNK(1,3),VNK(1,3),WK(1,3),RNB(1,3),VNB(1,3),WB(1,
     & 3),WBRCOM(1,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(1,3,3),RIKT(1,3,3),IKO(1,3,3),MKRK(1,3,3),CIB
     & (1,3,3)
      DOUBLE PRECISION WKK(1,3),VKK(1,3),DIK(1,3),RPP(1,3),RPK(1,3),RIK(
     & 1,3),RIK2(1,3)
      DOUBLE PRECISION RPRI(1,3),WIK(1,3),VIK(1,3),WIRK(1,3),RKWKK(1,3),
     & WKRPK(1,3),VIKWKR(1,3)
      DOUBLE PRECISION PERR(1),VERR(1),AERR(1),MULT(1),UFK(1,3),UTK(1,3)
     & ,MFK(1,3),MTK(1,3)
      DOUBLE PRECISION UTAU(1),MTAU(1),UACC(1),UVEL(1),UPOS(1)
      DOUBLE PRECISION S1,C1
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1
      DOUBLE PRECISION FS0(1),QDOT(1),OTK(1,3),ATK(1,3),AIOIWI(1,3),
     & FSTAR(1,3)
      DOUBLE PRECISION TSTAR(1,3),FSTARK(1,3),TSTARK(1,3),IKWK(1,3),
     & WKIKWK(1,3),GK(1,3),IKBWK(1,3),WKIKBWK(1,3)
      DOUBLE PRECISION W0W0(1),W1W1(1),W2W2(1),W0W1(1),W0W2(1),W1W2(1)
      DOUBLE PRECISION W00W11(1),W00W22(1),W11W22(1),WW(1,1),QRAUX(1)
      DOUBLE PRECISION MM(1,1),MLO(1,1),MDI(1),IKWPK(1,1,3),WORKS(1),
     & WORKSS(1,1)
      DOUBLE PRECISION WPK(1,1,3),VPK(1,1,3),VWRI(1,1,3)
      INTEGER WMAP(1),MULTMAP(1),JPVT(1),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      INTEGER I,J,QCHG,UCHG
C
      IF ((ROUSTATE .NE. 1) .AND. (ROUSTATE .NE. 2) .AND. (ROUSTATE
     &  .NE. 3)) THEN
        CALL SDSETERR(8,22)
        RETURN
      ENDIF
      IF (ROUSTATE .EQ. 1) THEN
        DO 50 I=1,1
          IF (PRESQ(I) .EQ. 1) THEN
            CALL SDSETERR(8,31)
          ENDIF
50      CONTINUE
      ENDIF
C
C See if time or any qs have changed since last call
C
      IF ((ROUSTATE .NE. 1) .AND. (TIMEIN .EQ. CURTIM)) THEN
        QCHG= 0
        DO 65 I=1,1
          IF (QIN(I) .NE. Q(I)) THEN
            QCHG= 1
            GOTO 70
          ENDIF
65      CONTINUE
70      CONTINUE
      ELSE
        QCHG= 1
      ENDIF
C
C If time and qs are unchanged, check us
C
      IF (QCHG .EQ. 0) THEN
        UCHG= 0
        DO 75 I=1,1
          IF (UIN(I) .NE. U(I)) THEN
            UCHG= 1
            GOTO 80
          ENDIF
75      CONTINUE
80      CONTINUE
      ELSE
        UCHG= 1
      ENDIF
      CURTIM= TIMEIN
      ROUSTATE= 2
      IF (QCHG .EQ. 0) THEN
C goto skipqs
        GOTO 190
      ENDIF
C
C Position-related variables need to be computed
C
      VPKFLG= 0
      MMFLG= 0
      MMLDUFLG= 0
      WWFLG= 0
      DO 100 I=1,1
        Q(I)= QIN(I)
100   CONTINUE
C
C Compute sines and cosines of q
C
      S1= DSIN(Q(1))
      C1= DCOS(Q(1))
C
C Compute across-axis direction cosines Cik
C
C
C Compute across-joint direction cosines Cib
C
C
C Compute gravity
C
C
C Compute cnk & cnb (direction cosines in N)
C
      CNB(1,1,1)= C1
      CNB(1,1,2)= -S1
      CNB(1,1,3)= 0D0
      CNB(1,2,1)= S1
      CNB(1,2,2)= C1
      CNB(1,2,3)= 0D0
      CNB(1,3,1)= 0D0
      CNB(1,3,2)= 0D0
      CNB(1,3,3)= 1D0
C
C Compute q-related auxiliary variables
C
C
C Compute rnk & rnb (mass center locations in N)
C
      RNB(1,1)= (1.5D0*S1)
      RNB(1,2)= -(1.5D0*C1)
      RNB(1,3)= 0D0
C
C Compute com (system mass center location in N)
C
      COM(1)= (1.5D0*((1D0/MK(1))*(MK(1)*S1)))
      COM(2)= -(1.5D0*((1D0/MK(1))*(MK(1)*C1)))
      COM(3)= 0D0
C skipqs
190   CONTINUE
      IF (UCHG .EQ. 0) THEN
C goto skipus
        GOTO 290
      ENDIF
C
C Velocity-related variables need to be computed
C
      INERFLG= 0
      DO 200 I=1,1
        U(I)= UIN(I)
200   CONTINUE
C
C Compute u-related auxiliary variables
C
C
C Compute wk & wb (angular velocities)
C
      WB(1,1)= 0D0
      WB(1,2)= 0D0
      WB(1,3)= U(1)
C
C Compute auxiliary variables involving wk
C
C
C Compute temporaries for use in SDRHS
C
      W2W2(1)= (U(1)*U(1))
C
C Compute vnk & vnb (mass center linear velocities in N)
C
      VNK(1,1)= (1.5D0*(U(1)*C1))
      VNK(1,2)= (1.5D0*(U(1)*S1))
      VNB(1,1)= VNK(1,1)
      VNB(1,2)= VNK(1,2)
      VNB(1,3)= 0D0
C
C Compute qdot (kinematical equations)
C
      QDOT(1)= U(1)
C skipus
290   CONTINUE
C
C Initialize applied forces and torques to zero
C
      DO 310 I=1,1
        DO 300 J=1,3
          UFK(I,J)= 0D0
          UTK(I,J)= 0D0
300     CONTINUE
310   CONTINUE
      DO 320 I=1,1
        UTAU(I)= 0D0
320   CONTINUE
      LTAUFLG= 0
      FS0FLG= 0
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain    3 adds/subtracts/negates
C                      13 multiplies
C                       2 divides
C                      34 assignments
C
C
      RETURN
      END
