      SUBROUTINE SDEQUIVHT(TAU)
      DOUBLE PRECISION TAU(1)
C
C Compute tree hinge torques to match effect of applied loads
C
      DOUBLE PRECISION GRAV(3),MK(1),IK(1,3,3),PIN(1,3)
      DOUBLE PRECISION RK(1,3),RI(1,3),PRES(1),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(1)
      INTEGER GRAVQ(3),MKQ(1),IKQ(1,3,3),PINQ(1,3),RKQ(1,3),RIQ(1,3),
     & PRESQ(1),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(1,3),RCOM(1,3),MKRCOMT(1,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(1),PSIK(1,3,3),
     & PSRCOM(1,3),PSRK(1,3),PSRI(1,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(1),QN(1),U(1),CNK(1,3,3),CNB(1,3,3)
      DOUBLE PRECISION RNK(1,3),VNK(1,3),WK(1,3),RNB(1,3),VNB(1,3),WB(1,
     & 3),WBRCOM(1,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(1,3,3),RIKT(1,3,3),IKO(1,3,3),MKRK(1,3,3),CIB
     & (1,3,3)
      DOUBLE PRECISION WKK(1,3),VKK(1,3),DIK(1,3),RPP(1,3),RPK(1,3),RIK(
     & 1,3),RIK2(1,3)
      DOUBLE PRECISION RPRI(1,3),WIK(1,3),VIK(1,3),WIRK(1,3),RKWKK(1,3),
     & WKRPK(1,3),VIKWKR(1,3)
      DOUBLE PRECISION PERR(1),VERR(1),AERR(1),MULT(1),UFK(1,3),UTK(1,3)
     & ,MFK(1,3),MTK(1,3)
      DOUBLE PRECISION UTAU(1),MTAU(1),UACC(1),UVEL(1),UPOS(1)
      DOUBLE PRECISION S1,C1
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1
      DOUBLE PRECISION FS0(1),QDOT(1),OTK(1,3),ATK(1,3),AIOIWI(1,3),
     & FSTAR(1,3)
      DOUBLE PRECISION TSTAR(1,3),FSTARK(1,3),TSTARK(1,3),IKWK(1,3),
     & WKIKWK(1,3),GK(1,3),IKBWK(1,3),WKIKBWK(1,3)
      DOUBLE PRECISION W0W0(1),W1W1(1),W2W2(1),W0W1(1),W0W2(1),W1W2(1)
      DOUBLE PRECISION W00W11(1),W00W22(1),W11W22(1),WW(1,1),QRAUX(1)
      DOUBLE PRECISION MM(1,1),MLO(1,1),MDI(1),IKWPK(1,1,3),WORKS(1),
     & WORKSS(1,1)
      DOUBLE PRECISION WPK(1,1,3),VPK(1,1,3),VWRI(1,1,3)
      INTEGER WMAP(1),MULTMAP(1),JPVT(1),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      DOUBLE PRECISION FSTAREQ(1,3),TSTAREQ(1,3)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(56,23)
        RETURN
      ENDIF
C
C Compute fstareq (forces)
C
      FSTAREQ(1,1)= ((9.8D0*(MK(1)*S1))-UFK(1,1))
      FSTAREQ(1,2)= ((9.8D0*(MK(1)*C1))-UFK(1,2))
C
C Compute tstareq (torques)
C
C
C Compute taus (RHS ignoring constraints and inertial forces)
C
      CALL SDDOVPK
      TAU(1)= (UTAU(1)-((1.5D0*FSTAREQ(1,1))-UTK(1,3)))
C
C Op counts below do not include called subroutines
C
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain    4 adds/subtracts/negates
C                       5 multiplies
C                       0 divides
C                       3 assignments
C
C
      RETURN
      END
