      SUBROUTINE SDCONSCHG
C
      DOUBLE PRECISION GRAV(3),MK(1),IK(1,3,3),PIN(1,3)
      DOUBLE PRECISION RK(1,3),RI(1,3),PRES(1),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(1)
      INTEGER GRAVQ(3),MKQ(1),IKQ(1,3,3),PINQ(1,3),RKQ(1,3),RIQ(1,3),
     & PRESQ(1),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(1,3),RCOM(1,3),MKRCOMT(1,3,3),
