      SUBROUTINE SDINFO(INFO)
      INTEGER INFO(50)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(1),INB(1),OUTB(1),NJNTDOF(1),NJNTC(1),NJNTP(1),
     & FIRSTQ(1),BALLQ(1),FIRSTM(1),FIRSTP(1)
      INTEGER TRANS(1)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
C
      INFO(1)= GROUND
      INFO(2)= NBOD
      INFO(3)= NDOF
      INFO(4)= NCONS
      INFO(5)= NLOOP
      INFO(6)= NLDOF
      INFO(7)= NLOOPC
      INFO(8)= NBALL
      INFO(9)= NLBALL
      INFO(10)= NPRES
      INFO(11)= NUSER
      INFO(12)= 0
C info entries from 13-50 are reserved
C
      RETURN
      END
C
      SUBROUTINE SDJNT(JOINT,INFO,TRAN)
      INTEGER JOINT,INFO(50),TRAN(6)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(1),INB(1),OUTB(1),NJNTDOF(1),NJNTC(1),NJNTP(1),
     & FIRSTQ(1),BALLQ(1),FIRSTM(1),FIRSTP(1)
      INTEGER TRANS(1)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      INTEGER I,OFFS
      INTEGER SDCHKJNUM
C
      IF (SDCHKJNUM(48,JOINT) .NE. 0) THEN
        RETURN
      ENDIF
      INFO(1)= JTYPE(JOINT)
      INFO(2)= 0
      OFFS= 0
      INFO(3)= INB(JOINT)
      INFO(4)= OUTB(JOINT)
      INFO(5)= NJNTDOF(JOINT)
      INFO(6)= NJNTC(JOINT)
      INFO(7)= NJNTP(JOINT)
      INFO(8)= FIRSTQ(JOINT)
      INFO(9)= BALLQ(JOINT)
      INFO(10)= FIRSTM(JOINT)
      INFO(11)= FIRSTP(JOINT)
C info entries from 12-50 are reserved
C
      DO 100 I=0,5
        IF (I  .LT.  NJNTDOF(JOINT)) THEN
          TRAN(I+1)= TRANS(OFFS+FIRSTQ(JOINT)+I)
        ELSE
          TRAN(I+1)= -1
        ENDIF
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDCONS(CONSNO,INFO)
      INTEGER CONSNO,INFO(50)
C
C
      INTEGER SDCHKUCNUM
      IF (SDCHKUCNUM(49,CONSNO) .NE. 0) THEN
        RETURN
      ENDIF
C There are no user constraints in this problem.
C
      RETURN
      END
C
      SUBROUTINE SDGENTIME(GENTM)
      INTEGER GENTM
C
C
      GENTM= TIMESTAMP
C
      RETURN
      END
C
C Done. CPU seconds used: TIMESTAMP  Memory used: TIMESTAMP bytes.
C Equation complexity:
C   sdstate:     3 adds    13 multiplies     2 divides    34 assignments
C   sdderiv:    12 adds    16 multiplies     1 divides    41 assignments
C   sdresid:    14 adds    15 multiplies     0 divides    28 assignments
C   sdreac:     10 adds     8 multiplies     0 divides    12 assignments
C   sdmom:       6 adds    12 multiplies     0 divides     9 assignments
C   sdsys:      11 adds    25 multiplies     0 divides    13 assignments
C
